    `P
      "Every document indexed via 'skl text document put'/'skl text \
       documents update' must belong to a source declared here first -- \
       there is no default/implicit source. 'skl text documents update' \
       defaults to every declared source in turn when --source is omitted, \
       which is also why a source must be declared before anything can be \
       indexed under it.";
    `P
      "For a $(b,git:)/$(b,github:) source, also records the branch \
       currently checked out at its own folder (see 'skl text document put \
       --overview' for where that is) -- fails if that folder doesn't exist, \
       isn't a git repository, or is in a detached HEAD state (no branch \
       checked out). This is what lets 'skl text documents update' index \
       such a source incrementally afterward (see its own --overview), by \
       checking that the branch checked out there at update time still \
       matches. Running this again on an already-declared \
       $(b,git:)/$(b,github:) source re-reads and re-records its current \
       branch: this is the only way to change which branch a source tracks, \
       e.g. after checking out a different one. A $(b,files:) source has \
       nothing analogous to check, so this is a plain no-op once declared.";
  ]

let cmd =
  let info = Cmd.info "put" ~doc ~man in
  Cmd.v info cmd_term
